fn digitProduct(n: i64) -> i64 {
    if n == 0 {
        return 0;
    }
    let mut product = 1;
    let mut num = n;
    while num > 0 {
        let digit = num % 10;
        if digit == 0 {
            num /= 10;
            continue;
        }
        product *= digit;
        num /= 10;
    }
    product
}
